INSERT INTO `categories` VALUES (1,'Thời sự','thoi-su','Tin tức thời sự trong nước nóng hổi, cập nhật liên tục.','#dc3545',1,'2026-10-21 18:54:09','2026-10-21 18:54:09'),(2,'Thế giới','the-gioi','Diễn biến nổi bật của tình hình quốc tế.','#0d6efd',1,'2026-10-21 18:54:09','2026-10-21 18:54:09'),(3,'Kinh doanh','kinh-doanh','Thị trường, doanh nghiệp, tài chính và đầu tư.','#198754',1,'2026-10-21 18:54:09','2026-10-21 18:54:09'),(4,'Công nghệ','cong-nghe','Xu hướng công nghệ, thiết bị số và chuyển đổi số.','#6f42c1',1,'2026-10-21 18:54:09','2026-10-21 18:54:09'),(5,'Thể thao','the-thao','Bóng đá, các giải đấu và gương mặt thể thao.','#fd7e14',1,'2026-10-21 18:54:09','2026-10-21 18:54:09'),(6,'Giải trí','giai-tri','Âm nhạc, điện ảnh và đời sống nghệ sĩ.','#d63384',1,'2026-10-21 18:54:09','2026-10-21 18:54:09'),(7,'Sức khỏe','suc-khoe','Kiến thức y tế, dinh dưỡng và chăm sóc sức khỏe.','#20c997',1,'2026-10-21 18:54:09','2026-10-21 18:54:09'),(8,'Giáo dục','giao-duc','Tuyển sinh, du học và câu chuyện học đường.','#0dcaf0',1,'2026-10-21 18:54:09','2026-10-21 18:54:09');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `comments`;
