/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `posts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(280) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `thumbnail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `views` int unsigned NOT NULL DEFAULT '0',
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `posts_slug_unique` (`slug`),
  KEY `posts_category_id_foreign` (`category_id`),
  KEY `posts_user_id_foreign` (`user_id`),
  KEY `posts_status_published_at_index` (`status`,`published_at`),
  CONSTRAINT `posts_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `posts_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `posts` WRITE;
/*!40000 ALTER TABLE `posts` DISABLE KEYS */;
INSERT INTO `posts` VALUES (1,1,1,'Thành phố triển khai nhiều giải pháp giảm ùn tắc giao thông giờ cao điểm','thanh-pho-trien-khai-nhieu-giai-phap-giam-un-tac-giao-thong-gio-cao-diem','Số liệu thống kê cho thấy mức tăng trưởng ổn định so với cùng kỳ năm trước. Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng.','<p>Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống. Giới phân tích nhận định thị trường sẽ còn nhiều biến động trong những tháng cuối năm. Sự kiện thu hút đông đảo người tham dự, tạo được nhiều dấu ấn tốt đẹp. Kế hoạch được triển khai theo nhiều giai đoạn, ưu tiên những khu vực có nhu cầu cấp thiết. Nhiều ý kiến đề xuất cần có cơ chế phối hợp chặt chẽ hơn giữa các bên liên quan.</p><p>Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Người tiêu dùng ngày càng chú trọng tới chất lượng và trải nghiệm thay vì chỉ quan tâm đến giá cả. Sự kiện thu hút đông đảo người tham dự, tạo được nhiều dấu ấn tốt đẹp. Trong thời gian tới, đơn vị sẽ tiếp tục mở rộng quy mô và đa dạng hóa các hoạt động. Đây được xem là bước đi quan trọng nhằm nâng cao hiệu quả và chất lượng phục vụ người dân.</p><h3>Tác động tới người dân</h3><p>Sự kiện thu hút đông đảo người tham dự, tạo được nhiều dấu ấn tốt đẹp. Người tiêu dùng ngày càng chú trọng tới chất lượng và trải nghiệm thay vì chỉ quan tâm đến giá cả. Các doanh nghiệp đang tích cực chuyển đổi số để thích ứng với xu hướng thị trường. Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp.</p><p>Các doanh nghiệp đang tích cực chuyển đổi số để thích ứng với xu hướng thị trường. Sự kiện thu hút đông đảo người tham dự, tạo được nhiều dấu ấn tốt đẹp. Đại diện đơn vị tổ chức cho biết mọi công tác chuẩn bị đã hoàn tất và sẵn sàng triển khai. Trong thời gian tới, đơn vị sẽ tiếp tục mở rộng quy mô và đa dạng hóa các hoạt động.</p><p>Theo ghi nhận của phóng viên, nhiều người dân bày tỏ sự quan tâm đặc biệt tới vấn đề này trong những ngày gần đây. Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội.</p><p>Số liệu thống kê cho thấy mức tăng trưởng ổn định so với cùng kỳ năm trước. Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống.</p><p>Sự kiện thu hút đông đảo người tham dự, tạo được nhiều dấu ấn tốt đẹp. Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng. Kế hoạch được triển khai theo nhiều giai đoạn, ưu tiên những khu vực có nhu cầu cấp thiết. Theo ghi nhận của phóng viên, nhiều người dân bày tỏ sự quan tâm đặc biệt tới vấn đề này trong những ngày gần đây.</p>','https://picsum.photos/seed/ayGvx76D/800/450','published',1,2569,'2026-10-08 02:58:49','2026-10-21 18:54:09','2026-10-21 18:54:09',NULL),(2,1,2,'Hàng nghìn tình nguyện viên tham gia chiến dịch làm sạch bờ biển','hang-nghin-tinh-nguyen-vien-tham-gia-chien-dich-lam-sach-bo-bien','Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội. Nhiều mô hình hay, cách làm sáng tạo đã được nhân rộng và mang lại hiệu quả thiết thực.','<p>Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội. Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống.</p><p>Giới phân tích nhận định thị trường sẽ còn nhiều biến động trong những tháng cuối năm. Bên cạnh những kết quả đạt được, vẫn còn không ít khó khăn, thách thức cần được tháo gỡ kịp thời. Các doanh nghiệp đang tích cực chuyển đổi số để thích ứng với xu hướng thị trường.</p><h3>Những điểm đáng chú ý</h3><p>Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội. Người tiêu dùng ngày càng chú trọng tới chất lượng và trải nghiệm thay vì chỉ quan tâm đến giá cả. Đại diện đơn vị tổ chức cho biết mọi công tác chuẩn bị đã hoàn tất và sẵn sàng triển khai.</p><p>Đây được xem là bước đi quan trọng nhằm nâng cao hiệu quả và chất lượng phục vụ người dân. Kế hoạch được triển khai theo nhiều giai đoạn, ưu tiên những khu vực có nhu cầu cấp thiết. Giới phân tích nhận định thị trường sẽ còn nhiều biến động trong những tháng cuối năm. Trong thời gian tới, đơn vị sẽ tiếp tục mở rộng quy mô và đa dạng hóa các hoạt động.</p><p>Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống. Người tiêu dùng ngày càng chú trọng tới chất lượng và trải nghiệm thay vì chỉ quan tâm đến giá cả. Các chuyên gia cho rằng đây là tín hiệu tích cực, mở ra nhiều cơ hội mới trong thời gian tới. Các doanh nghiệp đang tích cực chuyển đổi số để thích ứng với xu hướng thị trường. Theo ghi nhận của phóng viên, nhiều người dân bày tỏ sự quan tâm đặc biệt tới vấn đề này trong những ngày gần đây.</p><p>Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội. Nhiều mô hình hay, cách làm sáng tạo đã được nhân rộng và mang lại hiệu quả thiết thực. Số liệu thống kê cho thấy mức tăng trưởng ổn định so với cùng kỳ năm trước. Các chuyên gia cho rằng đây là tín hiệu tích cực, mở ra nhiều cơ hội mới trong thời gian tới.</p><p>Nhiều mô hình hay, cách làm sáng tạo đã được nhân rộng và mang lại hiệu quả thiết thực. Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội.</p>','https://picsum.photos/seed/3Nxbnt7Y/800/450','published',0,3715,'2026-10-16 12:08:06','2026-10-21 18:54:09','2026-10-21 18:54:09',NULL),(3,1,1,'Mở rộng mô hình dịch vụ công trực tuyến toàn trình cho người dân','mo-rong-mo-hinh-dich-vu-cong-truc-tuyen-toan-trinh-cho-nguoi-dan','Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội.','<p>Theo ghi nhận của phóng viên, nhiều người dân bày tỏ sự quan tâm đặc biệt tới vấn đề này trong những ngày gần đây. Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống. Nhiều ý kiến đề xuất cần có cơ chế phối hợp chặt chẽ hơn giữa các bên liên quan. Các doanh nghiệp đang tích cực chuyển đổi số để thích ứng với xu hướng thị trường.</p><p>Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng. Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống. Các chuyên gia cho rằng đây là tín hiệu tích cực, mở ra nhiều cơ hội mới trong thời gian tới. Đại diện đơn vị tổ chức cho biết mọi công tác chuẩn bị đã hoàn tất và sẵn sàng triển khai. Các doanh nghiệp đang tích cực chuyển đổi số để thích ứng với xu hướng thị trường.</p><h3>Tác động tới người dân</h3><p>Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Kế hoạch được triển khai theo nhiều giai đoạn, ưu tiên những khu vực có nhu cầu cấp thiết. Các chuyên gia cho rằng đây là tín hiệu tích cực, mở ra nhiều cơ hội mới trong thời gian tới. Nhiều ý kiến đề xuất cần có cơ chế phối hợp chặt chẽ hơn giữa các bên liên quan. Bên cạnh những kết quả đạt được, vẫn còn không ít khó khăn, thách thức cần được tháo gỡ kịp thời.</p><p>Giới phân tích nhận định thị trường sẽ còn nhiều biến động trong những tháng cuối năm. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội. Các chuyên gia cho rằng đây là tín hiệu tích cực, mở ra nhiều cơ hội mới trong thời gian tới. Đại diện đơn vị tổ chức cho biết mọi công tác chuẩn bị đã hoàn tất và sẵn sàng triển khai.</p><p>Trong thời gian tới, đơn vị sẽ tiếp tục mở rộng quy mô và đa dạng hóa các hoạt động. Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống. Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng. Số liệu thống kê cho thấy mức tăng trưởng ổn định so với cùng kỳ năm trước. Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội.</p>','https://picsum.photos/seed/PHO90gfr/800/450','published',0,4283,'2026-09-01 06:44:18','2026-10-21 18:54:09','2026-10-21 18:54:09',NULL),(4,1,2,'Nắng nóng kéo dài, ngành điện khuyến cáo sử dụng điện tiết kiệm','nang-nong-keo-dai-nganh-dien-khuyen-cao-su-dung-dien-tiet-kiem','Nhiều mô hình hay, cách làm sáng tạo đã được nhân rộng và mang lại hiệu quả thiết thực. Các doanh nghiệp đang tích cực chuyển đổi số để thích ứng với xu hướng thị trường.','<p>Đây được xem là bước đi quan trọng nhằm nâng cao hiệu quả và chất lượng phục vụ người dân. Số liệu thống kê cho thấy mức tăng trưởng ổn định so với cùng kỳ năm trước. Sự kiện thu hút đông đảo người tham dự, tạo được nhiều dấu ấn tốt đẹp.</p><p>Đây được xem là bước đi quan trọng nhằm nâng cao hiệu quả và chất lượng phục vụ người dân. Kế hoạch được triển khai theo nhiều giai đoạn, ưu tiên những khu vực có nhu cầu cấp thiết. Kết quả khảo sát mới nhất phản ánh mức độ hài lòng ngày càng cao của người dùng. Bên cạnh những kết quả đạt được, vẫn còn không ít khó khăn, thách thức cần được tháo gỡ kịp thời.</p><h3>Tác động tới người dân</h3><p>Giới trẻ hưởng ứng nhiệt tình, chia sẻ rộng rãi thông tin trên các nền tảng mạng xã hội. Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Giới phân tích nhận định thị trường sẽ còn nhiều biến động trong những tháng cuối năm.</p><p>Ban tổ chức khuyến cáo người dân cập nhật thông tin từ các nguồn chính thống. Lãnh đạo địa phương khẳng định sẽ tiếp tục theo dõi sát sao và có giải pháp phù hợp. Sự kiện thu hút đông đảo người tham dự, tạo được nhiều dấu 